# generate exact grid from initial and trace rays until encountering any occupied cell
R,C=18,22
g=[[1]*C for _ in range(R)]
orig={(8,3):9,(9,4):9,(8,6):6,(9,5):6,(10,4):7,(11,3):7,(10,5):2}
for p,v in orig.items():g[p[0]][p[1]]=v
for color,start,dirs in [(9,(8,3),[(-1,-1),(1,1)]),(6,(8,6),[(-1,1),(1,-1)]),(7,(10,4),[(-1,1),(1,-1)])]:
 for dr,dc in dirs:
  r,c=start[0]+dr,start[1]+dc
  while 0<=r<R and 0<=c<C and g[r][c]==1:
   g[r][c]=color;r+=dr;c+=dc
import json
print(json.dumps(g,separators=(',',':')))
